-export const definition = null;
-export const handler = null;
+const dialect = "https://json-schema.org/draft/2020-12/schema";
+const uuidPattern =
+  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/iu;
+const datePattern = /^\d{4}-\d{2}-\d{2}$/u;
+const identityPattern = /^\S{1,128}$/u;
+
+export const definition = {
+  id: "reviews.shift-deadline",
+  featureId: "reviews",
+  inputSchema: {
+    $schema: dialect,
+    type: "object",
+    required: ["applicationId", "effectiveDate"],
+    properties: {
+      applicationId: { type: "string", format: "uuid" },
+      effectiveDate: { type: "string", format: "date" },
+    },
+    additionalProperties: false,
+  },
+  output: {
+    schema: {
+      $schema: dialect,
+      type: "object",
+      required: ["applicationId", "effectiveDate"],
+      properties: {
+        applicationId: { type: "string", format: "uuid" },
+        effectiveDate: { type: "string", format: "date" },
+      },
+      additionalProperties: false,
+    },
+  },
+  execution: {
+    impact: "write",
+    confirmationRequired: true,
+    dryRunSupported: false,
+    idempotency: "required",
+    cancellationSupported: false,
+  },
+};
+
+export async function handler(input, context, application) {
+  const actorId = context?.invocationContext?.actor?.id;
+  const targetId = context?.invocationContext?.target?.id;
+  if (
+    typeof actorId !== "string" ||
+    !identityPattern.test(actorId) ||
+    typeof targetId !== "string" ||
+    !identityPattern.test(targetId)
+  ) {
+    throw new Error("invocation context denied");
+  }
+
+  const scope = await application.authorize({
+    actorId,
+    targetId,
+    applicationId: input.applicationId,
+  });
+  if (
+    scope === null ||
+    typeof scope !== "object" ||
+    typeof scope.tenantId !== "string" ||
+    !identityPattern.test(scope.tenantId)
+  ) {
+    throw new Error("tenant scope denied");
+  }
+
+  const result = await application.shiftReviewDeadline({
+    tenantId: scope.tenantId,
+    applicationId: input.applicationId,
+    effectiveDate: input.effectiveDate,
+  });
+  if (
+    result === null ||
+    typeof result !== "object" ||
+    Object.keys(result).length !== 2 ||
+    !uuidPattern.test(result.applicationId) ||
+    !datePattern.test(result.effectiveDate)
+  ) {
+    throw new Error("invalid application output");
+  }
+
+  return { applicationId: result.applicationId, effectiveDate: result.effectiveDate };
+}
+
 export const dataSource = null;
