 import assert from "node:assert/strict";
 import test from "node:test";
-import { definition } from "./candidate.mjs";
+import { definition, handler, dataSource } from "./candidate.mjs";
+import { createRegisteredOperationRuntime } from "./runtime-harness.mjs";

-test("extension is implemented and behaviorally verified", () => {
-  assert.notEqual(definition, null, "candidate is not implemented");
+const validInput = Object.freeze({
+  applicationId: "33333333-3333-4333-8333-333333333333",
+  effectiveDate: "2026-09-30",
+});
+
+function applicationFixture(options = {}) {
+  const { deny = false, mutationResult } = options;
+  const scope = Object.hasOwn(options, "authorizationResult")
+    ? options.authorizationResult
+    : { tenantId: "tenant-authorized" };
+  const calls = { authorize: [], shift: [] };
+  return {
+    calls,
+    async authorize(input) {
+      calls.authorize.push(input);
+      if (deny) throw new Error("domain access denied");
+      return scope;
+    },
+    async shiftReviewDeadline(input) {
+      calls.shift.push(input);
+      return mutationResult ?? { applicationId: input.applicationId, effectiveDate: input.effectiveDate };
+    },
+  };
+}
+
+function directContext(actorId, targetId) {
+  return Object.freeze({
+    dryRun: false,
+    invocationContext: Object.freeze({
+      requestId: "test-request",
+      actor: Object.freeze({ id: actorId }),
+      target: Object.freeze({ id: targetId, environment: "synthetic-staging" }),
+    }),
+  });
+}
+
+test("candidate exports a fixed write operation and no data source", () => {
+  assert.notEqual(definition, null);
+  assert.equal(definition.id, "reviews.shift-deadline");
+  assert.equal(definition.featureId, "reviews");
+  assert.equal(definition.execution.impact, "write");
+  assert.equal(definition.execution.confirmationRequired, true);
+  assert.equal(definition.execution.dryRunSupported, false);
+  assert.equal(definition.execution.idempotency, "required");
+  assert.equal(definition.execution.cancellationSupported, false);
+  assert.equal(typeof handler, "function");
+  assert.equal(dataSource, null);
+});
+
+test("handler authorizes with actor/target/applicationId then calls the one fixed service", async () => {
+  const application = applicationFixture();
+  const result = await handler(validInput, directContext("tester-one", "tenant-red"), application);
+  assert.deepEqual(application.calls.authorize, [
+    { actorId: "tester-one", targetId: "tenant-red", applicationId: validInput.applicationId },
+  ]);
+  assert.deepEqual(application.calls.shift, [
+    { tenantId: "tenant-authorized", applicationId: validInput.applicationId, effectiveDate: validInput.effectiveDate },
+  ]);
+  assert.deepEqual(result, { applicationId: validInput.applicationId, effectiveDate: validInput.effectiveDate });
+  assert.deepEqual(Object.keys(result).sort(), ["applicationId", "effectiveDate"]);
+});
+
+test("handler denies before any application call when invocation identity is malformed", async () => {
+  for (const [actorId, targetId] of [
+    [undefined, "tenant-red"],
+    ["", "tenant-red"],
+    [" has space", "tenant-red"],
+    ["x".repeat(129), "tenant-red"],
+    ["tester-one", null],
+  ]) {
+    const application = applicationFixture();
+    await assert.rejects(() => handler(validInput, directContext(actorId, targetId), application));
+    assert.equal(application.calls.authorize.length, 0);
+    assert.equal(application.calls.shift.length, 0);
+  }
+});
+
+test("handler denies when application authorization rejects the actor", async () => {
+  const application = applicationFixture({ deny: true });
+  await assert.rejects(() => handler(validInput, directContext("tester-one", "tenant-red"), application));
+  assert.equal(application.calls.shift.length, 0);
+});
+
+test("handler denies on an invalid or missing authorized tenant scope, but still authorizes exactly once", async () => {
+  for (const authorizationResult of [undefined, null, {}, { tenantId: 42 }, { tenantId: "" }, { tenantId: " x" }]) {
+    const application = applicationFixture({ authorizationResult });
+    await assert.rejects(() => handler(validInput, directContext("tester-one", "tenant-red"), application));
+    assert.equal(application.calls.authorize.length, 1);
+    assert.equal(application.calls.shift.length, 0);
+  }
+});
+
+test("handler rejects an invalid or leaking application mutation result instead of forwarding it", async () => {
+  const application = applicationFixture({
+    mutationResult: { applicationId: validInput.applicationId, effectiveDate: validInput.effectiveDate, extra: "leak" },
+  });
+  await assert.rejects(() => handler(validInput, directContext("tester-one", "tenant-red"), application));
+});
+
+test("registered runtime rejects missing or mismatched confirmation before any application effect", async () => {
+  const application = applicationFixture();
+  const runtime = await createRegisteredOperationRuntime({ definition, handler, application });
+
+  const missing = await runtime.create({ input: validInput, idempotencyKey: "confirm-key" });
+  assert.equal(missing.ok, false);
+
+  const mismatched = await runtime.create({
+    input: validInput,
+    idempotencyKey: "confirm-key",
+    confirmation: runtime.confirmation({ impact: "destructive" }),
+  });
+  assert.equal(mismatched.ok, false);
+  assert.equal(application.calls.authorize.length, 0);
+  assert.equal(application.calls.shift.length, 0);
+});
+
+test("registered runtime rejects invalid input at the schema boundary before the handler runs", async () => {
+  const application = applicationFixture();
+  const runtime = await createRegisteredOperationRuntime({ definition, handler, application });
+
+  const badUuid = await runtime.create({
+    input: { ...validInput, applicationId: "not-a-uuid" },
+    idempotencyKey: "schema-key-1",
+    confirmation: runtime.confirmation(),
+  });
+  assert.equal(badUuid.ok, false);
+
+  const unknownField = await runtime.create({
+    input: { ...validInput, unexpected: true },
+    idempotencyKey: "schema-key-2",
+    confirmation: runtime.confirmation(),
+  });
+  assert.equal(unknownField.ok, false);
+  assert.equal(application.calls.authorize.length, 0);
+  assert.equal(application.calls.shift.length, 0);
+});
+
+test("registered runtime succeeds end to end and returns exactly the closed output", async () => {
+  const application = applicationFixture();
+  const runtime = await createRegisteredOperationRuntime({ definition, handler, application });
+
+  const created = await runtime.create({
+    input: validInput,
+    idempotencyKey: "success-key",
+    confirmation: runtime.confirmation(),
+  });
+  assert.equal(created.ok, true);
+  await runtime.settle();
+  const stored = await runtime.get(created.run.id);
+  assert.equal(stored.state, "succeeded");
+  assert.deepEqual(stored.output, { applicationId: validInput.applicationId, effectiveDate: validInput.effectiveDate });
+  assert.equal(application.calls.shift.length, 1);
+});
+
+test("same idempotency key with changed valid input replays the original run with zero second mutation", async () => {
+  const application = applicationFixture();
+  const runtime = await createRegisteredOperationRuntime({ definition, handler, application });
+
+  const created = await runtime.create({
+    input: validInput,
+    idempotencyKey: "replay-key",
+    requestId: "correlation-one",
+    confirmation: runtime.confirmation(),
+  });
+  await runtime.settle();
+
+  const replay = await runtime.create({
+    input: { ...validInput, effectiveDate: "2026-10-15" },
+    idempotencyKey: "replay-key",
+    requestId: "correlation-two",
+    confirmation: runtime.confirmation(),
+  });
+  assert.equal(replay.ok, true);
+  assert.equal(replay.run.id, created.run.id);
+  await runtime.settle();
+  assert.equal(application.calls.shift.length, 1);
+});
+
+test("registered runtime fails the run without leaking application detail when the mutation result is invalid", async () => {
+  const application = applicationFixture({
+    mutationResult: { applicationId: validInput.applicationId, effectiveDate: validInput.effectiveDate, secretToken: "s3cr3t-sentinel" },
+  });
+  const runtime = await createRegisteredOperationRuntime({ definition, handler, application });
+
+  const created = await runtime.create({
+    input: validInput,
+    idempotencyKey: "invalid-output-key",
+    confirmation: runtime.confirmation(),
+  });
+  await runtime.settle();
+  const stored = await runtime.get(created.run.id);
+  assert.equal(stored.state, "failed");
+  assert.equal(JSON.stringify(stored).includes("s3cr3t-sentinel"), false);
+});
+
+test("domain denial through the registered runtime fails the run before any mutation", async () => {
+  const application = applicationFixture({ deny: true });
+  const runtime = await createRegisteredOperationRuntime({ definition, handler, application });
+
+  const created = await runtime.create({
+    input: validInput,
+    idempotencyKey: "denied-key",
+    confirmation: runtime.confirmation(),
+  });
+  await runtime.settle();
+  const stored = await runtime.get(created.run.id);
+  assert.equal(stored.state, "failed");
+  assert.equal(application.calls.shift.length, 0);
 });
